"""Negative-control functions from commit dbef131 (comments and prose removed)."""

SOURCE = 'def _scatter(engine: Any, owner: Any, intent: Any, count: int, within_ft: int, *, concealed: bool) -> None:\n    kit = _kit(engine, owner)\n    if kit is None:\n        return\n    config = _config(owner)\n    for cell in _scatter_cells(engine, owner, count, within_ft):\n        zone = _set(engine, owner, kit[\'action\'], intent, kit, cell, {**config, \'deploy\': None})\n        if zone is not None and concealed:\n            placed.update(engine, zone, aware=[a.entity_id for a in engine.state.actors.values() if a.team_id == owner.team_id])\n\ndef _relocate(engine: Any, mover: Any, traps: list[Any], cells: list[tuple[int, int]]) -> None:\n    from ..gate2_runtime_models import Position\n    if len(cells) < 2:\n        return\n    for owner in list(engine.state.actors.values()):\n        if owner.team_id == mover.team_id or not owner.active or _state(engine, owner, EMPTY_ROAD) is None:\n            continue\n        if engine._distance_actor_to_actor(owner, mover) > 60:\n            continue\n        flag = f\'trap_relocate_round_{engine.state.round_number}_{engine.state.current_slot_index}\'\n        if owner.turn_flags.get(flag):\n            continue\n        mine = [z for z in traps if z.owner_id == owner.entity_id and z.active and (not placed.data(z).get(\'shield\'))]\n        if not mine:\n            continue\n        zone = min(mine, key=lambda z: (engine.grid.distance_ft(z.center, mover.position), z.zone_id))\n        taken = {(z.center.x, z.center.y) for z in traps}\n        spots = [Position(x=zone.center.x + dx, y=zone.center.y + dy) for dx in (-2, -1, 0, 1, 2) for dy in (-2, -1, 0, 1, 2) if dx or dy]\n        spots = [c for c in spots if engine.grid.in_bounds((c.x, c.y)) and placed.free_square(engine, c) and ((c.x, c.y) not in taken) and (engine.grid.distance_ft(c, zone.center) <= 10)]\n        if not spots:\n            continue\n        spot = min(spots, key=lambda c: (engine.grid.distance_ft(c, mover.position), c.x, c.y))\n        if engine.grid.distance_ft(spot, mover.position) >= engine.grid.distance_ft(zone.center, mover.position):\n            continue\n        if not _ask(engine, getattr(engine, \'_active_intent\', None), owner, \'trap_relocate\', {\'use\': f\'Move a trap to ({spot.x}, {spot.y})\'}, f\'The Empty Road: {mover.display_name} moved inside your Emanation. Relocate your nearest trap toward it?\', \'The Empty Road\', [\'use\']):\n            continue\n        owner.turn_flags[flag] = True\n        placed.reshape(engine, zone, cells=(spot,))\n        placed.note(engine, zone.source_definition_id, owner, f"The Empty Road: {owner.display_name}\'s trap shifts to ({spot.x}, {spot.y}).")\n'
